-- 2027 资料核对第十六批（工科・计算机类国立/公立大学 7 所）。
-- 已于 2026-11-05 通过 scripts/apply-reviewed-sync-batch-16.cjs 经 Supabase REST 应用。
-- 保留为等价的可审计 SQL 工件；重复执行仅在目标行已存在时成立（下方校验在任一 slug 缺失时中止）。
-- 来源与限制见 docs/REDESIGN-AND-DATA.md 与 data/school-reviews.ts。
-- 受控同步：仅 7 条 University 记录按 slug upsert；无 DELETE、无批量导入、无表结构变更。
BEGIN;
DO $$ BEGIN
  IF (SELECT count(*) FROM "University" WHERE slug IN ('tuat', 'tum', 'kit', 'kyutech', 'nagaoka', 'toyohashi', 'aizu')) <> 7 THEN
    RAISE EXCEPTION '本批目标学校记录缺失，已中止，未应用任何更新';
  END IF;
END $$;
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'tuat', '东京农工大学', '東京農工大学', 'national', '国立（农工系）', '东京都府中市（农学部）/小金井市（工学部）', '官网2026年度以后入学：学部与大学院授课费642,960日元/年、入学料282,000日元、检定料学部17,000日元（大学院30,000日元）；研究生入学料84,600日元、授课费29,700日元/月。', '未核实（官网未设统一GPA门槛）', '2027私费外国人留学生入试要求2026年度EJU日语（含记述）；各学科另有指定EJU科目，未设统一JLPT等级。', '2027私费入试：TOEIC L&R 500分以上或TOEFL iBT 52分以上（2026-01-21起新量表按校方对照表换算，换算后52分以上）。', '农学部5学科与工学部6学科均设私费外国人留学生入试，各学科若干名；2027入试2027年1月15日至25日出愿、2月26日面试、3月6日合格发表。', '官网研究生：检定料9,800日元、入学料84,600日元、授课费29,700日元/月；是否需教授内诺按各研究科要项确认。', '2027私费外国人留学生入试：免除共通测试，按EJU成绩、指定英语检定、面试（含口头试问）与出身校调查书综合评定；出愿2027-01-15至01-25，面试2027-02-26，合格发表2027-03-06。', NULL, 'https://www.tuat.ac.jp/admission/nyushi_gakubu/youkou/', '["农学部5学科","工学部6学科","2027私费留学生入试","府中/小金井两校区"]'::jsonb, '[{"name":"农学部","level":"undergraduate","description":"生物生产学科、应用生物科学科、环境资源科学科、地域生态系统学科、共同兽医学科。","features":["5学科","各学科若干名"]},{"name":"工学部","level":"undergraduate","description":"生命工学科、生体医用系统工学科、应用化学科、化学物理工学科、机械系统工学科、知能信息系统工学科。","features":["6学科","各学科若干名"]},{"name":"农学府・工学府","level":"graduate","description":"官网另列先进学际科学府、生物系统应用科学府与联合农学研究科；各研究科出愿条件按要项确认。","features":["农学府","工学府","按研究科要项确认"]}]'::jsonb, '["农学/生命科学","工学方向","东京圈国立","需要日语EJU"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'tum', '东京海洋大学', '東京海洋大学', 'national', '国立（海洋系）', '东京都港区（品川）/江东区（越中岛）', '官网：学部与大学院授课费535,800日元/年、入学料282,000日元、检定料学部17,000日元（大学院30,000日元）；研究生入学料84,600日元、授课费29,700日元/月。', '未核实（官网未设统一GPA门槛）', '2027私费入试要求2026年度EJU日语；海洋生命科学部与海洋资源环境学部另需EJU数学（课程2）及理科2科目，海洋工学部为物理与化学。', '海洋生命科学部与海洋资源环境学部需TOEIC L&R 400分以上、TOEFL iBT 40分以上或IELTS 3.5以上等其中之一；海洋工学部私费入试不设英语资格要求。', '3学部8学科：海洋生命科学部3学科、海洋工学部3学科、海洋资源环境学部2学科；2027私费入试出愿2027-01-25至02-03，选抜含数学与英语个别测试及面试。', '官网研究生：检定料9,800日元、入学料84,600日元、授课费29,700日元/月；是否需教授内诺按各研究科要项确认。', '2027私费外国人留学生特别入试：EJU（日语、数学课程2、理科）+本校个别测试（数学与英语）+面试+志望理由书与成绩证明综合评定；出愿2027-01-25至02-03。', NULL, 'https://www.kaiyodai.ac.jp/entranceexamination/undergraduate/docs/international-students.html', '["3学部8学科","练习船实习","2027私费入试","品川/越中岛两校区"]'::jsonb, '[{"name":"海洋生命科学部","level":"undergraduate","description":"海洋生物资源学科、食品生产科学科、海洋政策文化学科。","features":["3学科","品川校区"]},{"name":"海洋工学部","level":"undergraduate","description":"海事系统工学科、海洋电子机械工学科、流通情报工学科。","features":["3学科","越中岛校区"]},{"name":"海洋资源环境学部","level":"undergraduate","description":"海洋环境科学科、海洋资源能源学科。","features":["2学科","品川校区"]},{"name":"大学院海洋科学技术研究科","level":"graduate","description":"设博士前期课程与博士后期课程；出愿条件按研究科要项确认。","features":["博士前期","博士后期"]}]'::jsonb, '["海洋/船舶","水产/食品","海洋资源能源","东京都心国立"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'kit', '京都工艺纤维大学', '京都工芸繊維大学', 'national', '国立（工科系）', '京都府京都市左京区', '官网：学部与大学院研究科授课费535,800日元/年（前期267,900、后期267,900日元）、入学料282,000日元、检定料学部17,000日元（大学院30,000日元）；研究生入学料84,600日元、授课费29,700日元/月。', '未核实（官网未设统一GPA门槛）', '2027私费入试要求EJU日语（听解・读解・听读解合计，不含记述）280分以上。', '2027私费入试需提交TOEFL成绩作为选拔材料，要项未公布统一分数线。', '工芸科学部4学域6课程（应用生物、应用化学、电子系统、信息工学、机械工学、设计与建筑）均招私费留学生；2027入试出愿2026-07-28至08-03、8月25日小论文与面试。', '官网研究生：检定料9,800日元、入学料84,600日元、授课费29,700日元/月；是否需教授内诺按各研究科要项确认。', '2027私费外国人留学生入试：免除共通测试，按EJU（日语280+、数学课程2 120+、理科指定科目）、TOEFL、小论文与面试综合评定；出愿2026-07-28至08-03，考试2026-08-25，合格发表2026-09-02。', NULL, 'https://www.kit.ac.jp/test_index/school_news/undergraduate/type_abroad/', '["4学域6课程","设计与建筑","2027入试已实施","京都"]'::jsonb, '[{"name":"应用生物学域（应用生物学课程）","level":"undergraduate","description":"私费入试需EJU日语280分以上、数学课程2 120分以上，理科从物理・化学・生物选2科目。","features":["EJU日语280+","数学120+"]},{"name":"物质・材料科学域（应用化学课程）","level":"undergraduate","description":"EJU日语、数学课程2及物理与化学。","features":["应用化学","EJU物理化学"]},{"name":"设计工学域","level":"undergraduate","description":"电子系统工学课程、信息工学课程、机械工学课程；EJU数学课程2及理科指定科目。","features":["3课程","EJU数学120+"]},{"name":"设计科学域（设计・建筑学课程）","level":"undergraduate","description":"分建筑课程与设计课程；EJU日语、数学课程2及理科1科目。","features":["建筑课程","设计课程"]}]'::jsonb, '["设计/建筑","材料/化学","机械/信息","京都"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'kyutech', '九州工业大学', '九州工業大学', 'national', '国立（工科系）', '福冈县北九州市（户畑）/饭塚市（饭塚）', '官网：入学料282,000日元、授课费535,800日元/年、检定料学部17,000日元（大学院30,000日元）。', '未核实（官网未设统一GPA门槛）', '2027私费入试需EJU日语；工学部另需数学课程2与物理・化学，情报工学部为数学课程2与理科2科目（按上年度要项，2027年度要项11月上旬公表）。', '2027私费入试需提交英语资格检定成绩并按校方换算表计分（上年度要项要求提交官方成绩证明，认可考试与换算以要项为准）。', '工学部5类与情报工学部4类均设私费外国人留学生选抜；2027选抜出愿2027-01-04至01-08、考试2月25-26日、合格发表3月8日。', '研究生制度以各研究科要项为准；本批未逐科核实受理条件与是否需要教授内诺。', '2027私费外国人留学生选抜：免除共通测试，按EJU、英语资格检定、本校个别学力检查与个人面试综合评定；出愿2027-01-04至01-08，考试2027-02-25、26，合格发表2027-03-08。', NULL, 'https://www.kyutech.ac.jp/examination/gs-expense.html', '["工学部5类","情报工学部4类","2027选抜日程已公布","北九州/饭塚"]'::jsonb, '[{"name":"工学部（工学科）","level":"undergraduate","description":"建设社会类、机械类、电气类、物质理工学类、综合类；2026年4月学部改組后的类制。","features":["5类","2026年4月改組"]},{"name":"情报工学部（情报工学科）","level":"undergraduate","description":"知能情报类、电子情报通信类、知的系统类、生命情报类。","features":["4类","情报/IT"]},{"name":"工学府・情报工学府・生命体工学研究科","level":"graduate","description":"官网列示的研究科/学府；各研究科出愿条件按要项确认。","features":["工学府","情报工学府","生命体工学研究科"]}]'::jsonb, '["九州留学","情报/IT","工科方向","低生活成本"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'nagaoka', '长冈技术科学大学', '長岡技術科学大学', 'national', '国立（技术科学系）', '新潟县长冈市', '官网：学部（第1学年）入学料282,000日元、授课费535,800日元/年、检定料17,000日元；2027年度金额尚未确定，以2026年度额为准。', '未核实（官网未设统一GPA门槛）', '2027私费入试要求2026年度EJU日语（读解、听解・听读解计分），并需数学课程2与理科2科目。', '2027私费入试要求2025年1月以后参加TOEIC L&R（公开测试）或TOEFL iBT；要项未公布统一最低分。', '工学部工学课程设机械、电气电子情报、情报・经营系统、物质生物、环境社会基盘5分野，各分野若干名；2027入试为书类选考，出愿2026-12-01至12-04、合格发表2027-01-22。', '研究生制度以各研究科要项为准；本批未逐科核实受理条件与是否需要教授内诺。', '2027私费外国人留学生入试：不设共通测试与本校笔试，按出愿书类、EJU成绩、TOEIC/TOEFL成绩综合选考；出愿2026-12-01至12-04，合格发表2027-01-22。', NULL, 'https://www.nagaokaut.ac.jp/admissions/exam/bachelor1/docs/index.html', '["工学课程5分野","书类选考","2027入试","长冈市"]'::jsonb, '[{"name":"工学部・工学课程","level":"undergraduate","description":"机械工学分野、电气电子情报工学分野、情报・经营系统工学分野、物质生物工学分野、环境社会基盘工学分野。","features":["5分野","各分野若干人"]},{"name":"大学院工学研究科","level":"graduate","description":"官网列示博士前期课程与博士后期课程；出愿条件按研究科要项确认。","features":["博士前期","博士后期"]}]'::jsonb, '["实践技术志向","制造业","低预算留学","新潟"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'toyohashi', '丰桥技术科学大学', '豊橋技術科学大学', 'national', '国立（技术科学系）', '爱知县丰桥市', '官网：入学料282,000日元、授课费535,800日元/年；入学时如有改定按改定额适用。', '未核实（官网未设统一GPA门槛）', '2027私费入试要求2026年度EJU日语280分以上（听解・读解・听读解合计，满分400，不含记述）。', 'TOEIC L&R 550分以上、TOEFL iBT 42分以上或IELTS 4.0以上（2025年1月以后受考）。', '2027年4月组织再编为「学际共创课程」1课程5分野（机械、电气、情报、化学、建设）一括募集（设置申请中）；私费入试出愿2026-12-14至12-18、2027-01-26选抜。', '研究生制度以各研究科要项为准；本批未逐科核实受理条件与是否需要教授内诺。', '2027私费外国人留学生选抜：按EJU（日语280+、数学课程2与理科2科目合计240+）、指定英语检定、出身校成绩证明与面试（英语与日语并用）综合评定；出愿2026-12-14至12-18，选抜2027-01-26，合格发表2027-02-05。', NULL, 'https://www.tut.ac.jp/exam/entrance/collect.html', '["2027组织再编","学际共创课程","1课程5分野","丰桥市"]'::jsonb, '[{"name":"学际共创课程（机械・电气・情报・化学・建设）","level":"undergraduate","description":"2027年4月起由现有5课程再编为1课程5分野，私费留学生若干名一括募集；再编为设置申请中，内容可能变更。","features":["5分野","一括募集","若干名"]},{"name":"大学院工学研究科","level":"graduate","description":"博士前期课程与博士后期课程；2027年度入学起计划再编为「学际共创专攻」。","features":["博士前期","博士后期","再编计划中"]}]'::jsonb, '["工科方向","实践技术","中部圈","2027新课程"]'::jsonb
