INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'aizu', '会津大学', '会津大学', 'public', '公立（计算机理工专门）', '福岛县会津若松市', '官网：入学检定料17,000日元、入学料564,000日元（福岛县居民282,000日元）、授课费520,800日元/年（前期与后期各分缴）。', '未核实（官网未设统一GPA门槛）', 'ICT Global Program全英语课程不要求日语；日语授课的一般选抜另行要求。', 'ICT Global Program 2027：TOEFL iBT 72分（2026-01-20前受考）/4.0（2026-01-21起新量表）、TOEIC L&R 785分、英检准1级或IELTS 5.5以上。', '日本首个计算机理工专门公立大学；ICT Global Program为全英语本科课程，2027年10月入学，2027-02-15至03-05提交PDF、03-19前寄达原件，05-14合格发表。', '研究生制度以研究科要项为准；本批未逐科核实受理条件。', 'ICT Global Program 2027：书类审查（含英语成绩，以及ACT/AP/EJU/国际A-Level/IB的数学与理科成绩），必要时线上面试；出愿2027-02-15至03-05（PDF）、原件至03-19，合格发表2027-05-14。', NULL, 'https://u-aizu.ac.jp/materials/', '["计算机理工专门","全英语本科","2027年10月入学","会津若松"]'::jsonb, '[{"name":"ICT Global Program（全英语课程）","level":"undergraduate","description":"教养科目与计算机理工专门科目全部以英语授课，可仅凭英语取得学位；另设分级日语课程。","features":["全英语授课","2027年10月入学","若干名"]},{"name":"大学院计算机理工学研究科","level":"graduate","description":"官网列示的研究科；出愿条件按研究科要项确认。","features":["按研究科要项确认"]}]'::jsonb, '["CS/IT方向","全英语本科","无需日语","2027年10月入学"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
